const $=id=>document.getElementById(id);
const models=[['随机森林','Random Forest','RF',.912,'100 棵树 · 最大深度 6'],['支持向量机','Support Vector Machine','SVM',.891,'RBF 核 · C = 1'],['逻辑回归','Logistic Regression','LR',.874,'L2 正则化 · C = 1'],['梯度提升树','Gradient Boosting','GB',.903,'100 轮 · 学习率 0.1'],['K 近邻','K-Nearest Neighbors','KNN',.842,'K = 5 · 欧氏距离'],['朴素贝叶斯','Gaussian Naive Bayes','NB',.821,'高斯分布 · 方差平滑']];
const steps=[['数据质控','真实缺失率 · MAF 过滤'],['特征预处理','填补 · 标准化（模拟）'],['多模型构建','分层交叉验证（模拟）'],['关联位点筛选','统计检验 · BH 校正（模拟）'],['结果汇总','模型比较 · 位点导出']];
let selected=new Set(models.map(m=>m[2])),busy=false,uploaded=false,config={maf:.05,missing:.05,sampleMissing:.2,folds:5,fdr:.05},timer;
const hits=Array.from({length:24},(_,i)=>({id:'rs'+(1042521+i*17893),chr:1+i%22,pos:1250376+i*287019,p:Math.pow(10,-9+i*.27),q:Math.min(.4,Math.pow(10,-4+i*.14)),importance:(.98-i*.023).toFixed(3)}));
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('toast').classList.remove('show'),3500)}
function navigate(v){if(!['overview','data','models','results','figures'].includes(v))throw Error('未知页面');document.querySelectorAll('.view').forEach(e=>e.classList.toggle('hidden',e.id!==v));document.querySelectorAll('nav button').forEach(e=>e.classList.toggle('active',e.dataset.view===v));$('pageTitle').textContent={overview:'SNP 分析工作台',data:'导入 SNP 数据',models:'机器学习模型配置',results:'候选位点分析结果',figures:'科研图与交叉验证演示'}[v]}
document.querySelectorAll('[data-view]').forEach(e=>e.onclick=()=>navigate(e.dataset.view));
$('flow').innerHTML=steps.map((s,i)=>`<div class="flow-item"><div class="step-icon">${String(i+1).padStart(2,'0')}</div><b>${s[0]}</b><small>${s[1]}</small></div>`).join('');
$('configModels').innerHTML=models.map(m=>`<label><input type="checkbox" value="${m[2]}" checked> <b>${m[0]}</b><p>${m[1]}</p><p>${m[4]}</p></label>`).join('');
function renderModels(){ $('modelCount').innerHTML=selected.size+' <small>models</small>';$('modelGrid').innerHTML=models.map(m=>`<div class="model-card"><span class="model-icon">${m[2]}</span><div><b>${m[0]}</b><small>${m[1]}</small></div><span class="check">${selected.has(m[2])?'✓':'—'}</span></div>`).join('');$('bars').innerHTML=models.filter(m=>selected.has(m[2])).sort((a,b)=>b[3]-a[3]).map(m=>`<div class="bar-row"><span>${m[0]}</span><div class="bar-track"><div style="width:${m[3]*100}%"></div></div><span>${m[3].toFixed(3)}</span></div>`).join('')}
function chart(){let svg='<svg viewBox="0 0 560 180" role="img" aria-label="演示数据曼哈顿图，横轴为22条染色体，纵轴为负对数p值">';for(let j=0;j<4;j++)svg+=`<line x1="30" y1="${20+j*40}" x2="550" y2="${20+j*40}" stroke="#edf1f3"/><text x="8" y="${24+j*40}" fill="#91a0a6" font-size="10">${9-j*3}</text>`;svg+='<line x1="30" y1="43" x2="550" y2="43" stroke="#dfa777" stroke-dasharray="4 4"/>';let seed=42;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};for(let c=1;c<=22;c++){for(let j=0;j<15;j++){let val=rand()*2.8;if((c===6||c===11||c===19)&&j<4)val=5+rand()*4;svg+=`<circle cx="${30+(c-1)*23.5+rand()*20}" cy="${145-val*13.8}" r="1.9" fill="${c%2?'#248f83':'#8ebdb3'}" opacity=".85"/>`}if(c%2||c===22)svg+=`<text x="${31+(c-1)*23.5}" y="171" font-size="9" fill="#88989f">${c}</text>`}svg+='</svg>';$('manhattan').innerHTML=svg}
function visibleHits(){return hits.filter(h=>(h.id+' '+h.chr).includes($('search').value.trim())&&($('filter').value!=='sig'||h.q<config.fdr))}
function renderRows(){$('rows').innerHTML=visibleHits().map(h=>`<tr><td>${h.id}</td><td>${h.chr}</td><td>${h.pos.toLocaleString()}</td><td>${h.p.toExponential(2)}</td><td>${h.q.toExponential(2)}</td><td>${h.importance}</td><td><span class="pill">${h.q<config.fdr?'候选显著':'未达阈值'}</span></td></tr>`).join('')||'<tr><td colspan="7">没有匹配的示例位点</td></tr>';$('hitCount').innerHTML=hits.filter(h=>h.q<config.fdr).length+' <small>candidates</small>'}
function download(name,text){const url=URL.createObjectURL(new Blob([text.startsWith('\uFEFF')?text:'\uFEFF'+text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function template(){download('SNP-DEMO-input-template.csv','sample_id,phenotype,rs10001,rs10002,rs10003\nS001,0,0,1,2\nS002,1,1,2,0\nS003,0,2,NA,1\nS004,1,1,0,2\n')}
function dosageTemplate(){download('SNP-DEMO-dosage-example.csv','sample_id,phenotype,rs20001,rs20002\nD001,0,0.12,1.87\nD002,1,1.03,0.54\nD003,0,NA,1.14\nD004,1,1.76,0.21\n')}
function rawTemplate(){download('SNP-DEMO-PLINK-raw-example.raw','FID IID PAT MAT SEX PHENOTYPE rs30001_A rs30002_G\nF01 S001 0 0 2 1 0 2\nF01 S002 0 0 1 2 1 NA\nF02 S003 0 0 2 1 2 0\nF02 S004 0 0 1 2 1 1\n')}
$('template').onclick=template;$('template2').onclick=template;$('templateDosage').onclick=dosageTemplate;$('templateRaw').onclick=rawTemplate;$('choose').onclick=()=>$('file').click();
async function run(){if(busy)throw Error('演示流程正在运行');busy=true;navigate('overview');$('run').disabled=true;$('flowState').textContent='运行中 · 模拟';const items=[...document.querySelectorAll('.flow-item')];items.forEach(e=>e.classList.remove('done','running'));$('progress').style.width='0%';try{for(let i=0;i<steps.length;i++){items[i].classList.add('running');$('status').textContent=`演示 ${i+1}/5：${steps[i][0]}${i===2?' · '+selected.size+' 个模型 / '+config.folds+' 折':''}`;await new Promise(r=>setTimeout(r,850));items[i].classList.remove('running');items[i].classList.add('done');$('progress').style.width=((i+1)*20)+'%'}$('flowState').textContent='演示完成';$('status').textContent=uploaded?'演示完成：上传数据仅检查了格式；结果仍来自固定模拟数据。':'演示完成：查看模拟模型评估和候选位点清单。';toast('演示完成，模拟结果可导出');return{status:'demo_complete',models:[...selected],simulated:true}}finally{busy=false;$('run').disabled=false}}
$('run').onclick=()=>run().catch(e=>toast(e.message));$('search').oninput=renderRows;$('filter').onchange=renderRows;$('export').onclick=()=>{const rows=visibleHits();download('SNP-DEMO-candidates.csv','data_source,SNP,chr,position,p_simulated,q_simulated,importance_simulated,status\n'+rows.map(h=>`SIMULATED,${h.id},${h.chr},${h.pos},${h.p},${h.q},${h.importance},${h.q<config.fdr?'candidate':'not_significant'}`).join('\n'));toast('已导出模拟位点结果')};
renderModels();renderRows();chart();
